      if (allowed.has(raw.public_response.error.code)) failure.public_response.error.code = raw.public_response.error.code;
    }
    return [{ json: failure }];
  }

  return [{ json: safeFailure(500, requestId, raw.internal_diagnostics) }];
} catch {
  return [{ json: safeFailure(500, null, null) }];
}
